      { "id": "value_3", "title": {"en": "Transformative Education", "es": "Educación Transformadora"}, "text": {"en": "We design educational programs that inspire curiosity, critical thinking, and a lasting commitment to conservation.", "es": "Diseñamos programas educativos que inspiran la curiosidad, el pensamiento crítico y el compromiso duradero con la conservación."}, "imageUrl": "https://biophiliaweb.org/images/valores/eucation.png"},
      { "id": "value_6", "title": {"en": "Science with Purpose", "es": "Ciencia con Propósito"}, "text": {"en": "We apply scientific research to understand and address local environmental challenges, generating practical solutions.", "es": "Aplicamos la investigación científica para comprender y abordar los desafíos ambientales locales, generando soluciones prácticas."}, "imageUrl": "https://biophiliaweb.org/images/valores/science.png"},
      { "id": "value_4", "title": {"en": "Social Equity", "es": "Equidad Social"}, "text": {"en": "We work to ensure that all communities, especially the most vulnerable, have access to a healthy environment.", "es": "Trabajamos para que todas las comunidades, en especial las más vulnerables, tengan acceso a un medio ambiente sano."}, "imageUrl": "https://biophiliaweb.org/images/valores/social.png"},
      { "id": "value_5", "title": {"en": "Community Leadership", "es": "Liderazgo Comunitario"}, "text": {"en": "We empower local leaders and organizations to be protagonists in the conservation of their natural resources.", "es": "Empoderamos a líderes y organizaciones locales para que sean protagonistas en la conservación de sus recursos naturales."}, "imageUrl": "https://biophiliaweb.org/images/valores/liderazgo.png"},
