-- 3.2 About Page
INSERT INTO `pages_content` (`page_name`, `content`) VALUES
('aboutPage', '{
  "banner": {
    "title": {"en": "About Us", "es": "Nosotros"},
    "imageUrl": "https://biophiliaweb.org/images/banners/Banner_Nosotros.jpeg"
  },
  "history": {
    "title": {"en": "Our History", "es": "Nuestra Historia"},
    "text": {"en": "Founded on the principle of biophilia — the innate human tendency to connect with nature — our institute was born from the shared passion of a group of educators, scientists, and community leaders who saw an urgent need to bridge the growing gap between urban life and the natural world. Since our inception, we have been committed to creating meaningful experiences that not only educate but also inspire concrete actions for the conservation of our planet, starting in our own communities.", "es": "Fundado en el principio de la biofilia —la innata tendencia humana a conectar con la naturaleza—, nuestro instituto nació de la pasión compartida de un grupo de educadores, científicos y líderes comunitarios que vieron la necesidad urgente de cerrar la creciente brecha entre la vida urbana y el mundo natural. Desde nuestros inicios, nos hemos dedicado a crear experiencias significativas que no solo educan, sino que también inspiran acciones concretas para la conservación de nuestro planeta, comenzando en nuestras propias comunidades."},
    "imageUrl": "https://biophiliaweb.org/images/otros/Nosotros_Historia.jpeg"
  },
  "mission": {
    "title": {"en": "Our Mission", "es": "Nuestra Misión"},
    "text": {"en": "To inspire and empower communities to build a sustainable and resilient future through education, science with purpose, and a deep connection with nature.", "es": "Inspirar y empoderar a las comunidades para construir un futuro sostenible y resiliente, a través de la educación, la ciencia con propósito y la conexión profunda con la naturaleza."},
    "imageUrl": "https://biophiliaweb.org/images/otros/Nosotros_Mision.jpeg",
    "imageAlt": "A diverse group of volunteers planting trees in a park."
  },
  "vision": {
    "title": {"en": "Our Vision", "es": "Nuestra Visión"},
    "text": {"en": "We envision a world where humanity coexists in harmony with nature, where all communities have equitable access to a healthy environment, and where conservation is an intrinsic value in society.", "es": "Visualizamos un mundo donde la humanidad coexiste en armonía con la naturaleza, donde todas las comunidades tienen acceso equitativo a un ambiente sano y donde la conservación es un valor intrínseco en la sociedad."},
    "imageUrl": "https://biophiliaweb.org/images/otros/Nosotros_Vision.jpeg",
    "imageAlt": "A breathtaking landscape with mountains and a clear lake."
  },
  "work": {
    "title": {"en": "Our Work", "es": "Nuestro Trabajo"},
    "text": {"en": "Our work is structured around key thematic areas designed to maximize our impact. From restoring urban ecosystems and promoting sustainable agriculture to training environmental leaders and advocating for fair policies, each of our programs is a seed of change. We collaborate directly with communities to co-design projects that are culturally relevant and respond to their specific needs, ensuring that every action we take is both effective and lasting.", "es": "Nuestro trabajo se articula en áreas temáticas clave, diseñadas para maximizar nuestro impacto. Desde la restauración de ecosistemas urbanos y la promoción de la agricultura sostenible, hasta la formación de líderes ambientales y la abogacía por políticas justas, cada uno de nuestros programas es una semilla de cambio. Colaboramos directamente con las comunidades para co-diseñar proyectos que sean culturalmente relevantes y que respondan a sus necesidades específicas, asegurando que cada acción que emprendemos sea tan efectiva como duradera."},
    "imageUrl": "https://biophiliaweb.org/images/otros/Nosotros_Trabajo.jpeg",
    "imageAlt": "A researcher taking notes while examining a plant in a lush forest."
  }
}');

